// ANSI escape sequences (e.g. `\x1B[34m`) used to colorize terminal output.
// eslint-disable-next-line no-control-regex
const ANSI_PATTERN = /\x1B\[[0-9;]*m/g;

// The Vitest addon prepends a "Click to debug..." banner to failing story errors
// (see addons/vitest setup-file). Strip it so the real error surfaces.
const DEBUG_BANNER_PATTERN = /Click to debug the error directly in Storybook:[^\n]*/g;

/** Remove ANSI colors and the Storybook debug banner from a piece of text. */
function stripDebugBanner(text: string): string {
  return text.replace(ANSI_PATTERN, '').replace(DEBUG_BANNER_PATTERN, '');
}

/** Return the first line of `text` that has non-whitespace content, trimmed. */
function firstNonEmptyLine(text: string | undefined): string | undefined {
  if (!text) {
    return undefined;
  }

  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (trimmed) {
      return trimmed;
    }
  }

  return undefined;
}

/**
 * Extract a concise, human-readable error message from a raw error message and/or stack.
 *
 * Storybook debug banners are stripped, then the first non-empty line of the cleaned message is
 * returned. If the message is empty, we fall back to the stack trace, and finally to
 * `'unknown error'` if both are empty.
 */
export function extractErrorMessage(
  message: string | undefined,
  stack: string | undefined
): string {
  const cleanedMessage = message ? stripDebugBanner(message) : undefined;
  const cleanedStack = stack ? stripDebugBanner(stack) : undefined;

  return firstNonEmptyLine(cleanedMessage) ?? firstNonEmptyLine(cleanedStack) ?? 'unknown error';
}

/** Return true if any report indicates that a story rendered nothing. */
export function detectEmptyRender(
  reports: readonly { type: string; result?: unknown }[] | undefined
): boolean {
  return (
    reports?.some(
      (report) =>
        report.type === 'render-analysis' &&
        (report.result as { emptyRender?: boolean } | undefined)?.emptyRender === true
    ) ?? false
  );
}

/** Normalize a raw test runner status into one of our three canonical statuses. */
function normalizeStatus(statusRaw: string | undefined): StoryTestResult['status'] {
  switch (statusRaw?.toLowerCase()) {
    case 'passed':
    case 'pass':
      return 'PASS';
    case 'failed':
    case 'fail':
      return 'FAIL';
    default:
      return 'PENDING';
  }
}

/**
 * Convert a raw test runner assertion into a normalized {@link StoryTestResult}.
 *
 * Returns `null` when there is no `storyId` to attribute the result to.
 */
export function toStoryTestResult(input: {
  storyId: string | undefined;
  statusRaw: string | undefined;
  errors?: readonly { message?: string; stack?: string }[];
  reports?: readonly { type: string; result?: unknown }[];
}): StoryTestResult | null {
  const { storyId, statusRaw, errors, reports } = input;

  if (storyId === undefined) {
    return null;
  }

  const status = normalizeStatus(statusRaw);
  const emptyRender = status === 'PASS' && detectEmptyRender(reports);

  const firstError = errors?.[0];
  const error = firstError ? extractErrorMessage(firstError.message, firstError.stack) : undefined;
  const stack = firstError?.stack;

  return {
    storyId,
    status,
    error,
    stack,
    emptyRender,
  };
}
